/// The bytes EUC-JP spells a character with, or None where it has none.
pub(crate) fn euc_jp_bytes_for(character: char) -> Option<Vec<u8>> {
    let point = character as u32;
    if point < 0x80 {
        return Some(vec![point as u8]);
    }
    let at = EUC_JP_CHARACTERS
        .binary_search_by_key(&point, |(held, _)| *held)
        .ok()?;
    let packed = EUC_JP_CHARACTERS[at].1;
    let mut bytes = Vec::with_capacity(3);
    for shift in [16u32, 8, 0] {
        let byte = ((packed >> shift) & 0xff) as u8;
        if bytes.is_empty() && byte == 0 {
            continue;
        }
        bytes.push(byte);
    }
    Some(bytes)
}

/// The character a run of EUC-JP bytes spells, alongside how many bytes it
/// took. None where the run opens no character the encoding names.
pub(crate) fn euc_jp_character(bytes: &[u8]) -> Option<(char, usize)> {
    let first = *bytes.first()?;
    if first < 0x80 {
        return Some((char::from(first), 1));
    }
    let width = if first == 0x8f { 3 } else { 2 };
    if bytes.len() < width {
        return None;
    }
    let mut packed = 0u32;
    for byte in &bytes[..width] {
        packed = (packed << 8) | *byte as u32;
    }
    let at = EUC_JP_CHARACTERS
        .iter()
        .position(|(_, held)| *held == packed)?;
    char::from_u32(EUC_JP_CHARACTERS[at].0).map(|held| (held, width))
}

/// The bytes EUC-JP spells a whole text with, or the first character it has
/// no bytes for.
pub(crate) fn euc_jp_bytes(text: &str) -> Result<Vec<u8>, char> {
    let mut bytes = Vec::with_capacity(text.len());
    for character in text.chars() {
        match euc_jp_bytes_for(character) {
            Some(spelled) => bytes.extend(spelled),
            None => return Err(character),
        }
    }
    Ok(bytes)
}

/// The text a run of EUC-JP bytes spells. A byte the encoding does not open a
/// character with stands for itself.
pub(crate) fn euc_jp_text(bytes: &[u8]) -> String {
    let mut written = String::with_capacity(bytes.len());
    let mut at = 0usize;
    while at < bytes.len() {
        match euc_jp_character(&bytes[at..]) {
            Some((character, width)) => {
                written.push(character);
                at += width;
            }
            None => {
                written.push(char::from(bytes[at]));
                at += 1;
            }
        }
    }
    written
}

/// The bytes ISO-2022-JP spells a run of text with. ASCII stands for itself,
/// and a run of Japanese characters is opened with `ESC $ B` and closed with
/// `ESC ( B`, each character written as the two JIS bytes for it.
pub(crate) fn iso_2022_jp_bytes(text: &str) -> Result<Vec<u8>, char> {
    let mut bytes = Vec::with_capacity(text.len());
    let mut in_japanese = false;
    for character in text.chars() {
        if character.is_ascii() {
            if in_japanese {
                bytes.extend_from_slice(b"\x1b(B");
                in_japanese = false;
            }
            bytes.push(character as u8);
            continue;
        }
        let Some(spelled) = euc_jp_bytes_for(character) else {
            return Err(character);
        };
        // Only the plane EUC-JP writes with two bytes of its own has a
        // spelling here.
        if spelled.len() != 2 || spelled[0] < 0xa1 || spelled[1] < 0xa1 {
            return Err(character);
        }
        if !in_japanese {
            bytes.extend_from_slice(b"\x1b$B");
            in_japanese = true;
        }
        bytes.push(spelled[0] - 0x80);
        bytes.push(spelled[1] - 0x80);
    }
    if in_japanese {
        bytes.extend_from_slice(b"\x1b(B");
    }
    Ok(bytes)
}

/// The text a run of ISO-2022-JP bytes spells, following the escapes that say
/// which set the bytes after them belong to.
pub(crate) fn iso_2022_jp_text(bytes: &[u8]) -> String {
    let mut written = String::with_capacity(bytes.len());
    let mut in_japanese = false;
    let mut at = 0usize;
    while at < bytes.len() {
        if bytes[at] == 0x1b && at + 2 < bytes.len() {
            match &bytes[at + 1..at + 3] {
                b"$B" | b"$@" => {
                    in_japanese = true;
                    at += 3;
                    continue;
                }
                b"(B" | b"(J" => {
                    in_japanese = false;
                    at += 3;
                    continue;
                }
                _ => {}
            }
        }
        if in_japanese && at + 1 < bytes.len() {
            let pair = [bytes[at] + 0x80, bytes[at + 1] + 0x80];
            match euc_jp_character(&pair) {
                Some((held, _)) => written.push(held),
                None => written.push(char::from(bytes[at])),
            }
            at += 2;
            continue;
        }
        written.push(char::from(bytes[at]));
        at += 1;
    }
    written
}
